k='z';E=lambda a,b=None:ev(k,a,b);F=lambda s,a,b,kind='inference':finding(k,s,a,b,kind)
rows=[(300,'圣殿之火清场引来风野报复；萧御提供无魔法值法系集结点情报换取夺宝机会。','侦察情报与组织指挥结合，骨龙尚未击杀。',16307,16371),(301,'萧御引走警戒者协助潜入，贪捡掉落险死，取得欺诈之玉。','新物有十秒嗅觉欺诈但佩戴死亡必掉，风险仍在。',16372,16486),(302,'风野援军到场、天龙继续顶骨龙，萧御决定深入人群。','资源合作被明确说成互利而非无条件友谊；潜入尚未成功。',16487,16536),(303,'凭匿迹和嗅觉欺诈穿过猎人区仍被德鲁伊阻挡；骨龙被公会杀死并将自爆。','个人装备解决一层障碍而不能通吃所有防线。',16537,16602),(304,'借自爆真空冲入抢两件掉落，换下贵重装备、关闭复活后被杀。','得宝与死亡同场，主动降低损失而非逃出生天。',16603,16664),(305,'风野堵援并牺牲六百贼仅回五十救尸复活；获骨龙牙刺、嗜血骨珠。','避免掉级但掉传说戒；个人收益对应集体伤亡成本。',16665,16716),(306,'萧御四杀展示能力后获救援者敬畏，牧师及时治疗也使第五目标无法杀。','强者评价提升但无法独定万人战；凤凰次数文字矛盾。',16717,16770),(307,'天龙让战士殿后保五千回城，誓言胜并复活己方；萧御练牙刺涂毒。','公会损益与个人战利品分开；下次猎人黑赛约定。',16771,16828),(308,'两类毒可并涂却不重复叠加；旁观云义三招困杀悍匪。','旧对手也在学习和成长，高级杀伤与低阶预判并用。',16829,16893),(309,'云义罗盘只示警不定位，萧御猜位排雷并三次突击，第三次受反制。','信息与技能数量各有限制，尚未形成胜利。',16894,16951),(310,'雷元素挡第三击并自爆，大雷暴重伤主角；原地隐身避开封逃路盲打。','双方承认平局且分开，不能写成萧御击败云义。',16952,17007)]
units=[unit(k,*r) for r in rows]
d={'worldbuilding':[F('欺诈之玉只在腰带生效，嗅觉欺诈十秒、五分钟冷却，死亡必掉；收包可避免掉落但无法冷却，形成取舍。',16479,16483,'fact')], 'characters':[F('风野愿牺牲多人一级换萧御一级，因为黑赛价值；萧御仍自认自由合作者。个人独行与组织托底同时存在。',16700,16705)], 'plot':[F('清场得罪三公会→外围骚扰拖延击杀→堵援→抢装死亡→救尸→集体胜利，个人线嵌在公会战因果内。',16333,16346)], 'style':[F('华丽魔法、即时技能点名与战果数字构成节奏；间歇由资源会计解释冒险值不值，阅读爽点兼具动作和收益。',16611,16644)], 'narrative':[F('罗盘先由云义视角交代只示警，萧御再据其动作推断；两方都有局部信息，读者能检验猜测。',16906,16921)], 'dialogue':[F('萧御直接说想拿宝、要求拖延；风野以到场时间回答，简短交易语言使联盟不靠空泛义气成立。',16335,16346)], 'pacing':[F('国战大场后以试验涂毒缓冲，再用声音引出云义小场，体量缩小但战术对手更精确。',16820,16840)], 'themes':[F('六百盗贼只剩五十的救援随后转成对个人强者的崇拜；这是文本的强者价值叙事，不能自动变成用户认可的创作价值。',16747,16765)], 'continuity':[F('287羽毛写涅槃三次，306改成五次，未说明升级；302说从未被玩家杀，286却被天龙狂龙杀，304又称第二次被挂。并列保留矛盾。',16718,16719)]}
c=[{'key':'fengye','name':'风野','aliases':[],'summary':'以公会战报复清场并托底黑赛投资，堵援、救尸和复活形成资源闭环。','goals':['提升公会收益与声望','维持萧御比赛价值'],'changes':['誓言赢公会战并升级','投入大批玩家救萧御'],'relationships':['互利合作萧御','圣殿之火结仇但顾忌两败俱伤'],'knowledge':['知欺诈之玉价值与必掉限制'],'source_anomalies':[],'evidence':E(16491,16499)+E(16665,16705)}, {'key':'yunyi','name':'云义','aliases':[],'summary':'雷法高手，从云天学预判并保持高级杀伤偏好，罗盘示警、雷元素和陷阱构成体系。','goals':['敌对阵营对决'],'changes':['与萧御战平','旧粗豪性格转稳为萧御观察推测'],'relationships':['云天闹翻只是传闻','承认萧御伯仲之间'],'knowledge':['判断萧御突击有限且正确'],'source_anomalies':[],'evidence':E(16873,16898)+E(16949,16950)+E(16995,17005)}, {'key':'xiaoyu','name':'萧御','aliases':[],'summary':'以死亡换史诗装备，经组织救尸维持等级；与云义战平后暴露接近法系的短板。','goals':['赚取战场资源与黑赛收入','挑战高手'],'changes':['掉一传说戒','骨龙牙刺可并涂两种毒和五咒','新嗅觉欺诈仍受冷却限制'],'relationships':['救援盗贼由不服到敬畏','与云义互认实力'],'knowledge':['预判原地不动破解封逃路','已见法系高手反制近身'],'source_anomalies':['凤凰次数三/五变动','从未玩家击杀与前后死亡冲突'],'evidence':E(16700,16714)+E(16830,16832)+E(16995,17005)}]
